const {chromium}=require('playwright-core'),assert=require('node:assert/strict'),zlib=require('node:zlib');
function pngFixture(width,height){
 const crc=data=>{let c=0xffffffff;for(const b of data){c^=b;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return (c^0xffffffff)>>>0;};
 const chunk=(type,data)=>{const t=Buffer.from(type),size=Buffer.alloc(4),sum=Buffer.alloc(4);size.writeUInt32BE(data.length);sum.writeUInt32BE(crc(Buffer.concat([t,data])));return Buffer.concat([size,t,data,sum]);};
 const head=Buffer.alloc(13);head.writeUInt32BE(width);head.writeUInt32BE(height,4);head[8]=8;head[9]=6;const row=Buffer.alloc(width*4+1);for(let i=1;i<row.length;i+=4){row[i]=70;row[i+1]=135;row[i+2]=200;row[i+3]=255;}
 return Buffer.concat([Buffer.from('89504e470d0a1a0a','hex'),chunk('IHDR',head),chunk('IDAT',zlib.deflateSync(Buffer.concat(Array.from({length:height},()=>row)))),chunk('IEND',Buffer.alloc(0))]);
}
(async()=>{
 const browser=await chromium.launch({executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',headless:true,args:['--no-sandbox']});
 try{
  const page=await browser.newPage({viewport:{width:1440,height:1100}}),errors=[];page.setDefaultTimeout(12000);page.on('pageerror',e=>errors.push(e.message));
  await page.goto(process.env.PREVIEW_URL||'http://127.0.0.1:8000');await page.locator('[data-tab=memos]').click();await page.locator('[data-new-kind=note]').click();
  const text='alpha BETA omega\nsecond target line\nlast ending';await page.locator('#memo-content').fill(text);
  const state=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('skycrm-web-preview-v1'))),position=()=>page.locator('.skycrm-local-image').first().evaluate(node=>richEditor.getIndex(Quill.find(node))),stored=()=>state().then(s=>s.memos[0].pages[0].delta.ops.filter(op=>op.insert?.localImage).map(op=>op.insert.localImage));
  const paste=async(name,width=200,height=80)=>page.evaluate(({data,name})=>{const transfer=new DataTransfer();transfer.items.add(new File([Uint8Array.from(atob(data),c=>c.charCodeAt(0))],name,{type:'image/png'}));document.querySelector('#memo-content').dispatchEvent(new ClipboardEvent('paste',{bubbles:true,cancelable:true,clipboardData:transfer}));},{data:pngFixture(width,height).toString('base64'),name});
  await page.locator('#memo-content').focus();await page.keyboard.press('Control+Home');for(let i=0;i<6;i++)await page.keyboard.press('ArrowRight');await paste('이동할 이미지.png');await page.waitForFunction(()=>document.querySelector('.skycrm-local-image')?.dataset.assetLoaded==='true');assert.equal(await page.locator('#insert-image,#image-input').count(),0);assert.equal(await position(),6);
  const memo=(await state()).memos[0].id,first=(await state()).memos[0].pages[0].id,imageId=(await stored())[0].id;
  await page.locator('.skycrm-local-image').click();assert.equal(await page.locator('[data-image-handle]').count(),4);assert.equal(await page.locator('#memo-image-tools').isVisible(),true);
  const initial=await page.locator('.skycrm-local-image').boundingBox(),handle=await page.locator('[data-image-handle=se]').boundingBox();
  await page.mouse.move(handle.x+handle.width/2,handle.y+handle.height/2);await page.mouse.down();await page.mouse.move(handle.x+handle.width/2+80,handle.y+handle.height/2+32,{steps:10});await page.mouse.up();
  await page.waitForFunction(()=>document.querySelector('.skycrm-local-image')?.dataset.assetLoaded==='true');let rect=await page.locator('.skycrm-local-image').boundingBox();assert.ok(Math.abs(rect.width-(initial.width+80))<2);assert.ok(Math.abs(rect.width/rect.height-2.5)<.05);assert.equal((await stored())[0].width,280);
  await page.locator('#memo-image-width').fill('260');await page.locator('#memo-image-width').press('Enter');await page.waitForFunction(()=>document.querySelector('.skycrm-local-image')?.dataset.assetLoaded==='true');assert.equal((await stored())[0].width,260);
  await page.locator('#memo-content').focus();await page.keyboard.press('Control+z');assert.equal((await stored())[0].width,280);await page.keyboard.press('Control+y');assert.equal((await stored())[0].width,260);assert.equal(await page.evaluate(()=>readRichText()),text);
  const textPoint=async needle=>page.evaluate(needle=>{const root=document.querySelector('#memo-content'),walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walk.nextNode()){const i=node.textContent.indexOf(needle);if(i>=0){const range=document.createRange();range.setStart(node,i);range.setEnd(node,i+1);const r=range.getBoundingClientRect();return {x:r.left+1,y:r.top+r.height/2};}}throw Error('Text not found');},needle);
  const dragTo=async point=>{const image=page.locator('.skycrm-local-image').first();await image.scrollIntoViewIfNeeded();const source=await image.boundingBox();await page.mouse.move(source.x+source.width/2,source.y+source.height/2);await page.mouse.down();await page.mouse.move(point.x,point.y,{steps:15});await page.mouse.up();await page.waitForFunction(()=>document.querySelector('.skycrm-local-image')?.dataset.assetLoaded==='true');};
  const targetIndex=await page.evaluate(()=>richSearchText().indexOf('target'));await dragTo(await textPoint('target'));assert.equal(await position(),targetIndex-1);assert.equal((await stored())[0].id,imageId);assert.equal((await stored())[0].width,260);assert.equal(await page.evaluate(()=>readRichText()),text);assert.equal(await page.locator('.skycrm-local-image').count(),1);
  await dragTo(await textPoint('alpha'));assert.equal(await position(),0);assert.equal(await page.evaluate(()=>readRichText()),text);
  // An out-of-editor drop is a cancellation, not deletion or a duplicate.
  await dragTo({x:60,y:150});assert.equal(await position(),0);assert.equal(await page.locator('.skycrm-local-image').count(),1);
  await page.locator('.skycrm-local-image').click();await page.locator('[data-image-action=original]').click();await page.waitForFunction(()=>document.querySelector('.skycrm-local-image')?.dataset.assetLoaded==='true');assert.equal((await stored())[0].width,undefined);assert.ok(Math.abs((await page.locator('.skycrm-local-image').boundingBox()).width-200)<2);await page.locator('#memo-content').focus();await page.keyboard.press('Control+z');assert.equal((await stored())[0].width,260);
  await page.locator('[data-add-page]').click();await page.locator('#memo-content').fill('독립 페이지');await page.locator(`[data-page-id="${first}"]`).click();await page.reload();await page.locator('[data-tab=memos]').click();await page.locator(`[data-memo-edit="${memo}"]`).click();await page.waitForFunction(()=>document.querySelector('.skycrm-local-image')?.dataset.assetLoaded==='true');assert.equal((await stored())[0].width,260);assert.equal(await position(),0);assert.equal(await page.evaluate(()=>readRichText()),text);
  await page.locator('.skycrm-local-image').click();await page.locator('[data-image-action=delete]').click();assert.equal(await page.locator('.skycrm-local-image').count(),0);await page.locator('#memo-content').focus();await page.keyboard.press('Control+z');await page.waitForFunction(()=>document.querySelector('.skycrm-local-image')?.dataset.assetLoaded==='true');assert.equal((await stored())[0].id,imageId);assert.equal((await stored())[0].width,260);
  // Keyboard movement is available without dragging and retains the same asset.
  await page.locator('.skycrm-local-image').click();await page.keyboard.press('Alt+ArrowRight');assert.equal(await position(),1);await page.keyboard.press('Alt+ArrowLeft');assert.equal(await position(),0);
  // Touch resizing uses the same pointer handles and remains inside a narrow editor.
  await page.setViewportSize({width:390,height:844});await page.locator('.skycrm-local-image').scrollIntoViewIfNeeded();await page.locator('.skycrm-local-image').click();const touchHandle=await page.locator('[data-image-handle=se]').boundingBox();const cdp=await page.context().newCDPSession(page);await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:1});const x=touchHandle.x+touchHandle.width/2,y=touchHandle.y+touchHandle.height/2;
  await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x,y}]});for(let i=1;i<=8;i++)await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:x-50*i/8,y:y-20*i/8}]});await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await page.waitForFunction(()=>document.querySelector('.skycrm-local-image')?.dataset.assetLoaded==='true');assert.ok(Math.abs((await stored())[0].width-210)<3);assert.equal(await page.evaluate(()=>readRichText()),text);
  // Large-image clicks can cause Quill to settle its native caret asynchronously.
  // The contextual controls must remain visible after that caret update.
  await page.setViewportSize({width:1440,height:1100});await page.locator('[data-add-page]').click();await paste('큰 이미지.png',600,180);await page.waitForFunction(()=>document.querySelector('.skycrm-local-image')?.dataset.assetLoaded==='true');await page.locator('.skycrm-local-image').click();await page.evaluate(()=>new Promise(resolve=>setTimeout(resolve,250)));assert.equal(await page.locator('#memo-image-frame').isVisible(),true);assert.equal(await page.locator('#memo-image-tools').isVisible(),true);
  assert.deepEqual(errors,[]);console.log('PASS Chromium: no image insertion button, image selection controls, aspect-ratio pointer/touch resize, numeric/original size, forward/backward text-position dragging, cancel outside, keyboard move, deletion/undo, and persisted size/position across pages/reload');
 }finally{await browser.close();}
})().catch(error=>{console.error(error);process.exit(1)});
